import { createContext, useState, useEffect } from 'react';
import axios from 'axios';

export const AuthContext = createContext();

export const AuthContextProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [token, setToken] = useState(sessionStorage.getItem('accessToken') || null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!token) return;

    const verifyToken = async () => {
      try {
        const res = await axios.get('http://localhost:5000/api/users/me', {
          headers: { Authorization: `Bearer ${token}` },
        });
        setCurrentUser(res.data);
      } catch (err) {
        console.error('Token verification error:', err.message);
        setCurrentUser(null);
        setToken(null);
        sessionStorage.removeItem('accessToken');
      }
    };

    verifyToken();
  }, [token]);

  const login = async (username, password) => {
    try {
      setError(null);
      const res = await axios.post('http://localhost:5000/api/auth/login', { username, password });
      setToken(res.data.accessToken);
      setCurrentUser(res.data.user);
      sessionStorage.setItem('accessToken', res.data.accessToken);
      sessionStorage.setItem('refreshToken', res.data.refreshToken);
      return true;
    } catch (err) {
      console.error('Login error:', err.message);
      setError(err.response?.data?.message || 'Login failed');
      throw new Error(err.response?.data?.message || 'Login failed');
    }
  };

  const logout = () => {
    setCurrentUser(null);
    setToken(null);
    sessionStorage.removeItem('accessToken');
    sessionStorage.removeItem('refreshToken');
  };

  const refreshToken = async () => {
    const refreshToken = sessionStorage.getItem('refreshToken');
    if (!refreshToken) return;

    try {
      const res = await axios.post('http://localhost:5000/api/auth/refresh-token', {
        refreshToken,
      });
      setToken(res.data.accessToken);
      sessionStorage.setItem('accessToken', res.data.accessToken);
    } catch (err) {
      console.error('Refresh token error:', err.message);
    }
  };

  return (
    <AuthContext.Provider value={{ currentUser, login, logout, refreshToken, error }}>
      {children}
    </AuthContext.Provider>
  );
};
